61	        source_id: ObjectId,
62	        damaged_player: PlayerId,
63	        amount: u32,
64	        description: String,
65	    },
66	    /// A watcher observing any damage (combat or non-combat) to a player.
67	    DamageToPlayerWatch {
68	        watcher_id: ObjectId,
