164	impl PendingTrigger {
165	    /// The player who controls this trigger.
166	    pub fn controller(&self) -> PlayerId {
167	        match self {
168	            PendingTrigger::SelfDies { controller, .. } => *controller,
169	            PendingTrigger::DeathWatch { controller, .. } => *controller,
170	            PendingTrigger::EnteredBattlefield { controller, .. } => *controller,
171	            PendingTrigger::EnterWatch { controller, .. } => *controller,
172	            PendingTrigger::CombatDamageToPlayer { controller, .. } => *controller,
173	            PendingTrigger::CombatDamageWatch { controller, .. } => *controller,
174	            PendingTrigger::DamageToPlayerWatch { controller, .. } => *controller,
175	            PendingTrigger::SpellCastWatch { controller, .. } => *controller,
176	            PendingTrigger::EndCombatTrigger { controller, .. } => *controller,
177	            PendingTrigger::UpkeepTrigger { controller, .. } => *controller,
178	            PendingTrigger::EndStepTrigger { controller, .. } => *controller,
179	            PendingTrigger::LeftBattlefield { .. } => PlayerId(255),
180	            PendingTrigger::AttacksTrigger { controller, .. } => *controller,
181	            PendingTrigger::BlocksTrigger { controller, .. } => *controller,
182	            PendingTrigger::AttackWatch { controller, .. } => *controller,
183	            PendingTrigger::CombatDamageToCreature { controller, .. } => *controller,
184	            PendingTrigger::BecomesBlockedTrigger { controller, .. } => *controller,
185	            PendingTrigger::StateTriggered { controller, .. } => *controller,
186	        }
187	    }
188	
189	    /// Display name for the stack view, including what the trigger does.
190	    pub fn display_name(&self, registry: &crate::cards::CardRegistry) -> String {
191	        let card_name = |card_id: CardId| {
192	            registry.card_data(card_id)
193	                .map(|d| d.name)
194	                .unwrap_or_else(|| "Unknown".into())
195	        };
196	        match self {
197	            PendingTrigger::SelfDies { dead_card_id, description, .. } => {
198	                if description.is_empty() {
199	                    format!("{}'s dies trigger", card_name(*dead_card_id))
200	                } else {
201	                    format!("{}'s dies trigger ({})", card_name(*dead_card_id), description)
202	                }
203	            }
204	            PendingTrigger::DeathWatch { watcher_card_id, description, .. } => {
205	                if description.is_empty() {
206	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
207	                } else {
208	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
209	                }
210	            }
211	            PendingTrigger::EnteredBattlefield { card_id, description, .. } => {
212	                if description.is_empty() {
213	                    format!("{}'s ETB trigger", card_name(*card_id))
214	                } else {
215	                    format!("{}'s ETB trigger ({})", card_name(*card_id), description)
216	                }
217	            }
218	            PendingTrigger::EnterWatch { watcher_card_id, description, .. } => {
219	                if description.is_empty() {
220	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
221	                } else {
222	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
223	                }
224	            }
225	            PendingTrigger::CombatDamageToPlayer { creature_card_id, description, .. } => {
226	                if description.is_empty() {
227	                    format!("{}'s combat damage trigger", card_name(*creature_card_id))
228	                } else {
229	                    format!("{}'s combat damage trigger ({})", card_name(*creature_card_id), description)
230	                }
231	            }
232	            PendingTrigger::CombatDamageWatch { watcher_card_id, description, .. }
233	            | PendingTrigger::DamageToPlayerWatch { watcher_card_id, description, .. } => {
234	                if description.is_empty() {
235	                    format!("{}'s triggered ability", card_name(*watcher_card_id))
236	                } else {
237	                    format!("{}'s triggered ability ({})", card_name(*watcher_card_id), description)
238	                }
239	            }
